# Angular weights for L ≥ 1: for the components 𝒴_a = u₁^a u₂^{L−a} (u = x + iy, natural parity l₁ + l₂ = L, M = L),
#   W_ac(r₁, r₂, r₁₂) = Σ_M conj(T_a^M) T_c^M   (sum over all components generated by the lowering operator = (2L+1) × rotational average)
# is built exactly with rationals as a polynomial in r₁², r₂², r₁₂². ⟨f𝒴_a|g𝒴_c⟩ = 8π²/(2L+1) ∫ r₁r₂r₁₂ f g W_ac.
module Angular

export angular_weight

const Q = Complex{Rational{BigInt}}
const P = Dict{NTuple{6,Int},Q}
add!(p::P, m, c) = (iszero(c) || (v = get(p, m, zero(Q)) + c; iszero(v) ? delete!(p, m) : (p[m] = v)); p)
function deriv(p::P, i)
    r = P(); for (m, c) in p; m[i] == 0 && continue; add!(r, Base.setindex(m, m[i] - 1, i), c * m[i]); end; r
end
mulvar(p::P, i) = (r = P(); for (m, c) in p; add!(r, Base.setindex(m, m[i] + 1, i), c); end; r)
scale(p::P, s) = (r = P(); for (m, c) in p; add!(r, m, c * s); end; r)
plus!(a::P, b::P) = (for (m, c) in b; add!(a, m, c); end; a)
# L₋ = Σ_particles (L_x − i L_y), L_x = −i(y∂z − z∂y), L_y = −i(z∂x − x∂z)
function lminus(p::P)
    r = P()
    for (x, y, z) in ((1, 2, 3), (4, 5, 6))
        Lx = plus!(scale(mulvar(deriv(p, z), y), -im), scale(mulvar(deriv(p, y), z), im))
        Ly = plus!(scale(mulvar(deriv(p, x), z), -im), scale(mulvar(deriv(p, z), x), im))
        plus!(r, plus!(Lx, scale(Ly, -im)))
    end
    r
end
# u₁^a u₂^b (u = x + iy)
function upow(a, b)
    p = P((0, 0, 0, 0, 0, 0) => one(Q))
    for _ in 1:a; p = plus!(mulvar(p, 1), scale(mulvar(p, 2), im)); end
    for _ in 1:b; p = plus!(mulvar(p, 4), scale(mulvar(p, 5), im)); end
    p
end
conjp(p::P) = (r = P(); for (m, c) in p; add!(r, m, conj(c) * (im)^(0)); end; r)   # the variables are real, so only coefficients are conjugated
function mul(a::P, b::P)
    r = P(); for (m, c) in a, (n, d) in b; add!(r, m .+ n, c * d); end; r
end
"""
    weight(L, a, c)

Evaluate W_ac at r₁ = (0,0,R₁), r₂ = (R₂ sinθ, 0, R₂ cosθ) and return it as a polynomial Dict{(i,j,k)} in R₁, R₂, R₁₂ (even powers).
"""
# prefactor v = z₁u₂ − z₂u₁ for unnatural parity
vpoly() = P((0, 0, 1, 1, 0, 0) => one(Q), (0, 0, 1, 0, 1, 0) => Q(im), (1, 0, 0, 0, 0, 1) => -one(Q), (0, 1, 0, 0, 0, 1) => -Q(im))
function _weight_full(L, a, c, p=0)
    Ta = [p == 0 ? upow(a, L - a) : mul(vpoly(), upow(a, L - 1 - a))]; Tc = [p == 0 ? upow(c, L - c) : mul(vpoly(), upow(c, L - 1 - c))]
    for _ in 1:2L; push!(Ta, lminus(Ta[end])); push!(Tc, lminus(Tc[end])); end
    W = P()
    for (k, M) in enumerate(L:-1:-L)
        # squared normalization of the lowering operator: Π_{M'=M+1}^{L} (L+M')(L−M'+1)
        n2 = prod(big(L + Mp) * (L - Mp + 1) for Mp in M+1:L; init=big(1))
        plus!(W, scale(mul(conjp(Ta[k]), Tc[k]), 1 // n2))
    end
    _frame_reduce(W)
end

# ── Lowering per particle ──────────────────────────────────────────────────────────────
# L₋ = L₋⁽¹⁾ + L₋⁽²⁾ commute, so the multiplet of f₁(r⃗₁) f₂(r⃗₂) is T^{L−k} = Σ_j C(k, j) (L₋⁽¹⁾)^j f₁ · (L₋⁽²⁾)^{k−j} f₂.
# One-particle polynomials are kept as monomials u^p v^q z^s in (u, v, z) = (x+iy, x−iy, z). L₋ = v∂_z − 2z∂_u lowers m = p − q by 1
# and keeps p + q + s = l, so (L₋)^k u^l has only ⌊k/2⌋+1 terms u^{l−k+t} v^t z^{k−2t} (in (x,y,z) it would grow to ~l² terms).
# Restricting to the frame (x₁ = y₁ = 0 ⇔ u₁ = v₁ = 0, y₂ = 0 ⇔ u₂ = v₂ = x₂) is a ring homomorphism, so each factor is
# restricted before the product. The result equals the six-variable implementation exactly (checked in the tests).
const P3 = Dict{NTuple{3,Int},Q}                 # powers of (u, v, z)
add3!(p::P3, m, c) = (iszero(c) || (v = get(p, m, zero(Q)) + c; iszero(v) ? delete!(p, m) : (p[m] = v)); p)
scale3(p::P3, s) = (r = P3(); for (m, c) in p; add3!(r, m, c * s); end; r)
plus3!(a::P3, b::P3) = (for (m, c) in b; add3!(a, m, c); end; a)
d3(p::P3, i) = (r = P3(); for (m, c) in p; m[i] == 0 && continue; add3!(r, Base.setindex(m, m[i] - 1, i), c * m[i]); end; r)  # ∂u, ∂v, ∂z
function lminus3(p::P3)                          # v∂z − 2z∂u
    r = P3()
    for ((a, b, z), c) in p
        z > 0 && add3!(r, (a, b + 1, z - 1), c * z)
        a > 0 && add3!(r, (a - 1, b, z + 1), c * (-2a))
    end
    r
end
upow3(a; z::Int=0) = P3((a, 0, z) => one(Q))    # z^z (x + iy)^a
# Cartesian derivatives: ∂x = ∂u + ∂v, ∂y = i(∂u − ∂v), ∂z; ∇² = 4∂u∂v + ∂z²
dxyz3(p::P3, i) = i == 1 ? plus3!(d3(p, 1), d3(p, 2)) : i == 2 ? scale3(plus3!(d3(p, 1), scale3(d3(p, 2), -1)), im) : d3(p, 3)
lap3(p::P3) = plus3!(scale3(d3(d3(p, 1), 2), 4), d3(d3(p, 3), 3))
# component as f₁ ⊗ f₂ sums: natural parity u₁^a u₂^{L−a}, unnatural (z₁u₂ − z₂u₁) u₁^a u₂^{b} (b = L−1−a)
_factors(L, a, p) = p == 0 ? [(one(Q), upow3(a), upow3(L - a))] :
    [(one(Q), upow3(a; z=1), upow3(L - a)), (-one(Q), upow3(a + 1), upow3(L - 1 - a; z=1))]
function _lowered(f::P3, n)                      # [f, L₋f, …, L₋ⁿ f]
    out = [f]; for _ in 1:n; push!(out, isempty(out[end]) ? P3() : lminus3(out[end])); end; out
end
fr1(p::P3) = [(m[3], c) for (m, c) in p if m[1] == 0 && m[2] == 0]         # particle 1 on the z axis (u = v = 0)
fr2(p::P3) = [((m[1] + m[2], m[3]), c) for (m, c) in p]                     # particle 2 in the xz plane (u = v = x; _combine! adds equal keys)
# Σ_j C(k,j) X_j ⊗ Y_{k−j} as frame monomials (0,0,e₁,x₂,0,z₂) of six variables (X, Y already restricted per particle)
function _combine!(out::P, coef, X, Y, k)
    for j in max(0, k - length(Y) + 1):min(k, length(X) - 1)
        (isempty(X[j+1]) || isempty(Y[k-j+1])) && continue
        b = coef * binomial(big(k), big(j))
        for (e, c) in X[j+1], ((x, z), d) in Y[k-j+1]
            add!(out, (0, 0, e, x, 0, z), b * c * d)
        end
    end
    out
end
# multiplet T^M (M = L..−L) restricted to the frame (six-variable P, nonzero only at (0,0,e₁,x₂,0,z₂))
function _multiplet_frame(L, a, p)
    fs = [(c, fr1.(_lowered(f1, 2L)), fr2.(_lowered(f2, 2L))) for (c, f1, f2) in _factors(L, a, p)]
    [reduce((o, t) -> _combine!(o, t[1], t[2], t[3], k), fs; init=P()) for k in 0:2L]
end
const _MFCACHE = Dict{NTuple{3,Int},Vector{P}}()     # frame multiplets per component (reused by all (L+1)(L+2)/2 pairs; caller holds _LOCK)
_multiplet_frame_cached(L, a, p) = get!(() -> _multiplet_frame(L, a, p), _MFCACHE, (L, a, p))
function weight(L, a, c, p=0)
    Ta = _multiplet_frame_cached(L, a, p); Tc = _multiplet_frame_cached(L, c, p)
    W = P()
    for (k, M) in enumerate(L:-1:-L)
        n2 = prod(big(L + Mp) * (L - Mp + 1) for Mp in M+1:L; init=big(1))
        plus!(W, scale(mul(conjp(Ta[k]), Tc[k]), 1 // n2))
    end
    _frame_reduce(W)
end

# evaluate an invariant six-variable polynomial in the frame as a polynomial in (R₁, R₂, R₁₂) (coefficients Q or Complex{BigFloat})
function _frame_reduce(W::Dict{NTuple{6,Int},C}) where {C}
    # frame: x₁ = y₁ = 0, z₁ = R₁, x₂ = R₂ s, y₂ = 0, z₂ = R₂ c; terms with y vanish. s² = 1 − c², c = (R₁² + R₂² − R₁₂²)/(2R₁R₂),
    # i.e. 2R₁R₂ c = R₁² + R₂² − R₁₂². Terms are first collected by (power of R₁, power of R₂, power of c), then expanded
    # trinomially (expanding per monomial costs L⁴).
    acc = Dict{NTuple{3,Int},C}()
    for (m, coef) in W
        (m[1] == 0 && m[2] == 0 && m[5] == 0) || continue
        e1 = m[3]; sx = m[4]; cz = m[6]      # R₁^{e1} (R₂ s)^{sx} (R₂ c)^{cz}
        isodd(sx) && continue                # odd powers of s vanish in the rotational average (W is a real invariant)
        h = sx ÷ 2
        for t in 0:h                         # s^{sx} = (1 − c²)^{h}
            key = (e1, sx + cz, cz + 2t)
            acc[key] = get(acc, key, zero(C)) + coef * (binomial(big(h), big(t)) * (-1)^t)
        end
    end
    out = Dict{NTuple{3,Int},C}()
    for ((e1, r2p, cpow), f) in acc
        iszero(f) && continue
        # R₁^{e1} R₂^{r2p} c^{cpow}, c^{cpow} = (R₁²+R₂²−R₁₂²)^{cpow} / (2R₁R₂)^{cpow}
        for i in 0:cpow
            bi = binomial(big(cpow), big(i))
            for j in 0:cpow-i
                k = cpow - i - j
                mult = bi * binomial(big(cpow - i), big(j)) * (-1)^k
                key = (e1 + 2i - cpow, r2p + 2j - cpow, 2k)
                out[key] = get(out, key, zero(C)) + f * (mult // big(2)^cpow)
            end
        end
    end
    filter!(x -> !iszero(x[2]), out)
end

# multiplet T^M (M = L..−L, from the lowering operator) and squared normalizations n2 (T̃^M = T^M/√n2 is the M component of component a)
function _multiplet(L::Int, a::Int, p::Int)
    T = [p == 0 ? upow(a, L - a) : mul(vpoly(), upow(a, L - 1 - a))]
    for _ in 1:2L; push!(T, lminus(T[end])); end
    [(T[k], prod(big(L + Mp) * (L - Mp + 1) for Mp in M+1:L; init=big(1))) for (k, M) in enumerate(L:-1:-L)]
end

# Clebsch–Gordan ⟨j₁ m₁ j₂ m₂ | J M⟩ (Racah formula, integer j)
function _cg(j1, m1, j2, m2, J, M)
    (m1 + m2 == M && abs(j1 - j2) <= J <= j1 + j2 && abs(m1) <= j1 && abs(m2) <= j2 && abs(M) <= J) || return big(0.0)
    f = factorial ∘ big
    pre = (2J + 1) * f(J + j1 - j2) * f(J - j1 + j2) * f(j1 + j2 - J) // f(j1 + j2 + J + 1) *
          f(J + M) * f(J - M) * f(j1 - m1) * f(j1 + m1) * f(j2 - m2) * f(j2 + m2)
    s = big(0) // 1
    for k in 0:j1+j2+J
        d = (k, j1 + j2 - J - k, j1 - m1 - k, j2 + m2 - k, J - j2 + m1 + k, J - j1 - m2 + k)
        all(>=(0), d) || continue
        s += (-1)^k // prod(f, d)
    end
    sqrt(BigFloat(pre)) * BigFloat(s)
end

const _CWCACHE = Dict{Tuple{Int,Int,Int,Int,Int,Int,Int},Vector{Tuple{NTuple{3,Int},Complex{BigFloat}}}}()
"""
    coupled_weight(L0, a, Lp, c, kind; unnatural0=false, unnaturalp=false) -> Vector{((p, q, s), w::Complex{BigFloat})}

Angular part of transition elements (Bethe logarithm). For component a of the initial state (L0) and c of the intermediate
state (Lp), the invariant X = Σ_{M,q,M'} ⟨L0 M 1 q|Lp M'⟩ conj(T̃'^{M'}) K_q T̃^M of the CG-coupled vector operator, as a polynomial
in (R₁, R₂, R₁₂). K_q are unit spherical components; `kind` = 1: r⃗₁, 2: r⃗₂, 3: ∇₁, 4: ∇₂. The sum over M of ⟨Lp|J|L0⟩ equals
|∫ r₁r₂r₁₂ f g X|² (element measure) / N₀ (the package's S).
"""
function coupled_weight(L0::Int, a::Int, Lp::Int, c::Int, kind::Int; unnatural0::Bool=false, unnaturalp::Bool=false)
    p0, pp = Int(unnatural0), Int(unnaturalp)
    lock(_LOCK) do
        get!(_CWCACHE, (L0, a, Lp, c, kind, p0, pp)) do
            setprecision(BigFloat, 512) do
                T0 = _multiplet(L0, a, p0); Tp = _multiplet(Lp, c, pp); E = _multiplet(1, 1, 0)
                X = Dict{NTuple{6,Int},Complex{BigFloat}}()
                mx = big(0.0)                       # size of the terms before summing (scale for discarding cancellation residue)
                for (kq, q) in enumerate(1:-1:-1), (k0, M) in enumerate(L0:-1:-L0)
                    Mp = M + q; abs(Mp) <= Lp || continue
                    cg = _cg(L0, M, 1, q, Lp, Mp); iszero(cg) && continue
                    kp = Lp - Mp + 1
                    e, nE = E[kq]                     # e_q·r⃗₁ (components are coefficients of variables 1..3), Σ_q |e_q·r|²/nE = 2r²
                    t, n0 = T0[k0]
                    K = P()
                    for i in 1:3
                        ei = get(e, Base.setindex((0, 0, 0, 0, 0, 0), 1, i), zero(Q)); iszero(ei) && continue
                        v = kind <= 2 ? mulvar(t, i + 3(kind - 1)) : deriv(t, i + 3(kind - 3))
                        plus!(K, scale(v, ei))
                    end
                    w = cg / sqrt(BigFloat(Tp[kp][2] * n0 * 2nE))
                    for (m, x) in mul(conjp(Tp[kp][1]), K)
                        v = w * Complex{BigFloat}(x); mx = max(mx, abs(v))
                        X[m] = get(X, m, zero(Complex{BigFloat})) + v
                    end
                end
                # invariance check: equal values at two rotated points
                ev(cf) = sum(x * prod(cf .^ m) for (m, x) in X; init=zero(Complex{BigFloat}))
                r = BigFloat[0.3, -0.7, 0.5, 0.9, 0.2, -0.4]
                θ = BigFloat(0.7); Rm = [cos(θ) 0 sin(θ); 0 1 0; -sin(θ) 0 cos(θ)] * [cos(1.1θ) -sin(1.1θ) 0; sin(1.1θ) cos(1.1θ) 0; 0 0 1]
                r2 = vcat(Rm * r[1:3], Rm * r[4:6])
                v1, v2 = ev(r), ev(r2)
                abs(v1 - v2) <= 1e-100 * (1 + abs(v1)) || error("coupled weight is not invariant (L0=$L0, a=$a, Lp=$Lp, c=$c, kind=$kind): $v1 vs $v2")
                out = _frame_reduce(X)
                # discard cancellation residue relative to the size of the terms (for identically vanishing couplings the maximum itself is residue)
                mx *= 64                             # multinomial factors of the frame conversion
                for (k, v) in out
                    abs(v) <= 1e-100 * mx && (delete!(out, k); continue)
                    (all(iseven, k) && all(>=(0), k)) || error("odd or negative power $k in the frame polynomial ($v)")
                end
                sort!([(k, v) for (k, v) in out]; by=first)
            end
        end
    end
end

# Pointwise evaluation (quadrature operators and σ² for L ≥ 1, observables.jl): T_a^M for all M and its derivatives, keeping only the
# monomials z₁^i x₂^j z₂^k that survive in the frame r₁ = (0, 0, R₁), r₂ = (R₂ s, 0, R₂ c).
# Field order: T, ∂x₁, ∂y₁, ∂z₁, ∂x₂, ∂y₂, ∂z₂, ∇₁²T, ∇₂²T, ∇₁·∇₂T. Weights w_M = 1/(squared lowering normalization), so
# Σ_M w_M conj(T_a^M) T_c^M = W_ac (the same sum as weight).
const _FCACHE = Dict{NTuple{4,Int},Vector{Tuple{Rational{BigInt},Vector{Vector{Tuple{NTuple{3,Int},Complex{Rational{BigInt}}}}}}}}()
# reference implementation for checks (lowers a six-variable polynomial 2L times; slow for large L)
function _component_fields_full(L::Int, a::Int; unnatural::Bool=false)
    p = Int(unnatural)
    begin
        begin
            T = [p == 0 ? upow(a, L - a) : mul(vpoly(), upow(a, L - 1 - a))]
            for _ in 1:2L; push!(T, lminus(T[end])); end
            frame(q::P) = sort!([((m[3], m[4], m[6]), c) for (m, c) in q if m[1] == 0 && m[2] == 0 && m[5] == 0])
            map(enumerate(L:-1:-L)) do (k, M)
                n2 = prod(big(L + Mp) * (L - Mp + 1) for Mp in M+1:L; init=big(1))
                t = T[k]
                g = [deriv(t, i) for i in 1:6]
                lap1 = plus!(plus!(deriv(g[1], 1), deriv(g[2], 2)), deriv(g[3], 3))
                lap2 = plus!(plus!(deriv(g[4], 4), deriv(g[5], 5)), deriv(g[6], 6))
                mp = plus!(plus!(deriv(g[1], 4), deriv(g[2], 5)), deriv(g[3], 6))
                (1 // n2, [frame(q) for q in (t, g..., lap1, lap2, mp)])
            end
        end
    end
end

function component_fields(L::Int, a::Int; unnatural::Bool=false)
    p = Int(unnatural)
    lock(_LOCK) do
        get!(_FCACHE, (L, a, p, 0)) do
            fs = map(_factors(L, a, p)) do (c, f1, f2)
                A = _lowered(f1, 2L); B = _lowered(f2, 2L)
                # per-field factors of particles 1 and 2: T, ∂x₁, ∂y₁, ∂z₁, ∂x₂, ∂y₂, ∂z₂, ∇₁², ∇₂²; ∇₁·∇₂ is Σ_i ∂ᵢ ⊗ ∂ᵢ
                d1 = [fr1.(dxyz3.(A, i)) for i in 1:3]; d2 = [fr2.(dxyz3.(B, i)) for i in 1:3]
                (c=c, A=fr1.(A), B=fr2.(B), d1=d1, d2=d2, l1=fr1.(lap3.(A)), l2=fr2.(lap3.(B)))
            end
            frame(q::P) = sort!([((m[3], m[4], m[6]), c) for (m, c) in q])
            map(enumerate(L:-1:-L)) do (kk, M)
                k = kk - 1
                n2 = prod(big(L + Mp) * (L - Mp + 1) for Mp in M+1:L; init=big(1))
                fld(sel) = (o = P(); for f in fs; (X, Y) = sel(f); _combine!(o, f.c, X, Y, k); end; o)
                t = fld(f -> (f.A, f.B))
                g = [fld(f -> (f.d1[i], f.B)) for i in 1:3]
                append!(g, [fld(f -> (f.A, f.d2[i])) for i in 1:3])
                lap1 = fld(f -> (f.l1, f.B)); lap2 = fld(f -> (f.A, f.l2))
                mp = P(); for f in fs, i in 1:3; _combine!(mp, f.c, f.d1[i], f.d2[i], k); end
                (1 // n2, [frame(q) for q in (t, g..., lap1, lap2, mp)])
            end
        end
    end
end

const _CACHE = Dict{NTuple{4,Int},Vector{Tuple{NTuple{3,Int},Rational{BigInt}}}}()
const _LOCK = ReentrantLock()

"""
    angular_weight(L, a, c; unnatural=false) -> Vector{((p, q, s), w)}

W_ac = Σ w r₁^p r₂^q r₁₂^s (rationals; p, q, s even and ≥ 0), W_ca = W_ac.
`unnatural = true` uses the unnatural-parity components 𝒴_a = (z₁u₂ − z₂u₁) u₁^a u₂^{L−1−a} (a = 0..L−1).
"""
function angular_weight(L::Int, a::Int, c::Int; unnatural::Bool=false)
    p = Int(unnatural); Lc = L - p
    (0 <= a <= Lc && 0 <= c <= Lc) || throw(ArgumentError("components must be in 0..$Lc (L=$L, a=$a, c=$c, unnatural=$unnatural)"))
    a > c && return angular_weight(L, c, a; unnatural=unnatural)
    lock(_LOCK) do
        get!(_CACHE, (L, a, c, p)) do
            w = weight(L, a, c, p)
            all(v -> iszero(imag(v)), values(w)) || error("W is not real (L=$L, a=$a, c=$c)")
            sort!([(k, real(v)) for (k, v) in w])
        end
    end
end

const _LEG = Dict{NTuple{4,Int},Vector{Tuple{Int,Vector{Tuple{Int,Int,Rational{BigInt}}}}}}()
# ∫₋₁¹ P_l(x) x^j dx (nonzero only for j ≥ l with j − l even)
_pmom(l, j) = j < l || isodd(j - l) ? big(0) // 1 :
    big(2)^(l + 1) * factorial(big(j)) * factorial(big((j + l) ÷ 2)) // (factorial(big((j - l) ÷ 2)) * factorial(big(j + l + 1)))

"""
    legendre_components(L, a, c; unnatural=false) -> [(l, [(P, Q, w)])]

Legendre components W_ac = Σ_l w_l(r₁, r₂) P_l(x) in x = cos θ₁₂, w_l = Σ w r₁^P r₂^Q (substitute r₁₂² = r₁² + r₂² − 2r₁r₂x and
project). The exchange mirror pair W_{0L} ∝ r₁^L r₂^L P_L(x) has the single term l = L; the pair (1, L−1) has l ∈ {L−2, L}.
"""
function legendre_components(L::Int, a::Int, c::Int; unnatural::Bool=false)
    a > c && return legendre_components(L, c, a; unnatural=unnatural)
    p = Int(unnatural)
    w = angular_weight(L, a, c; unnatural=unnatural)
    lock(_LOCK) do
        get!(_LEG, (L, a, c, p)) do
            fast = _legendre_fast(w)
            fast === nothing ? _legendre_slow(w) : fast
        end
    end
end

# W is rotationally invariant, hence homogeneous in r₁ and in r₂ (W = r₁^P r₂^Q g(x), x = cos θ₁₂). g(x) = W(1, 1, x) = Σ_m V_m (2 − 2x)^m
# (V_m = sum of the coefficients of r₁₂^{2m}) is rewritten in powers of x and projected on Legendre polynomials in O(L²).
# If W is not homogeneous (W(2,1,x)/W(1,1,x) not a power of 2), return nothing and the caller uses the trinomial expansion.
function _legendre_fast(w)
    isempty(w) && return Tuple{Int,Vector{Tuple{Int,Int,Rational{BigInt}}}}[]
    any(t -> isodd(t[1][3]), w) && return nothing
    Wv(r1, r2, x) = sum(v * big(r1)^pp * big(r2)^qq * (big(r1)^2 + big(r2)^2 - 2big(r1) * big(r2) * x)^(s ÷ 2) for ((pp, qq, s), v) in w)
    P = Q = -1
    for x0 in (big(1) // 3, big(2) // 7, big(-3) // 5)
        w11 = Wv(1, 1, x0); iszero(w11) && continue
        r1, r2 = Wv(2, 1, x0) / w11, Wv(1, 2, x0) / w11
        (isone(denominator(r1)) && isone(denominator(r2)) && ispow2(numerator(r1)) && ispow2(numerator(r2))) || return nothing
        P1, Q1 = trailing_zeros(numerator(r1)), trailing_zeros(numerator(r2))
        (P >= 0 && (P1, Q1) != (P, Q)) && return nothing
        P, Q = P1, Q1
    end
    P < 0 && return nothing
    V = Dict{Int,Rational{BigInt}}()
    for ((_, _, s), v) in w
        V[s ÷ 2] = get(V, s ÷ 2, 0 // 1) + v
    end
    jmax = maximum(keys(V))
    g = zeros(Rational{BigInt}, jmax + 1)                                  # g(x) = Σ_k g[k+1] x^k
    for (m, v) in V, k in 0:m
        g[k+1] += v * big(2)^m * binomial(big(m), big(k)) * (isodd(k) ? -1 : 1)
    end
    out = Tuple{Int,Vector{Tuple{Int,Int,Rational{BigInt}}}}[]
    for l in 0:jmax
        cl = sum((g[j+1] * _pmom(l, j) for j in l:jmax if !iszero(g[j+1])); init=big(0) // 1) * (2l + 1) // 2
        iszero(cl) || push!(out, (l, [(P, Q, cl)]))
    end
    out
end

function _legendre_slow(w)
        begin
            X = Dict{NTuple{3,Int},Rational{BigInt}}()           # r₁^P r₂^Q x^j
            for ((pp, qq, s), v) in w
                m = s ÷ 2
                for i in 0:m, j in 0:m-i                         # (r₁²)^i (r₂²)^j (−2r₁r₂x)^{m−i−j}
                    k = m - i - j
                    co = v * factorial(big(m)) // (factorial(big(i)) * factorial(big(j)) * factorial(big(k))) * big(-2)^k
                    key = (pp + 2i + k, qq + 2j + k, k)
                    X[key] = get(X, key, 0 // 1) + co
                end
            end
            jmax = maximum(k[3] for k in keys(X); init=0)
            out = Tuple{Int,Vector{Tuple{Int,Int,Rational{BigInt}}}}[]
            for l in 0:jmax
                proj = Dict{NTuple{2,Int},Rational{BigInt}}()
                for ((P, Q, j), v) in X
                    iszero(v) && continue
                    t = _pmom(l, j); iszero(t) && continue
                    proj[(P, Q)] = get(proj, (P, Q), 0 // 1) + v * t * (2l + 1) // 2
                end
                terms = sort!([(P, Q, v) for ((P, Q), v) in proj if !iszero(v)])
                isempty(terms) || push!(out, (l, terms))
            end
            out
        end
end

"""
    angular_lmin(L, a, c; unnatural=false) -> Int

Lowest Legendre degree in W_ac (`legendre_components`): L for the mirror pair W_{0L}, c − a for L ≤ 7. For elements whose σ and
r₁₂ exponents do not depend on x, the x integral with r₁₂^C (even C, 0 ≤ C < 2 l_min) vanishes exactly, so `_element_table_direct`
skips those elements.
"""
angular_lmin(L::Int, a::Int, c::Int; unnatural::Bool=false) =
    (cs = legendre_components(L, a, c; unnatural=unnatural); isempty(cs) ? typemax(Int) ÷ 4 : cs[1][1])

end
